import "server-only";

import { createHash } from "node:crypto";
import { and, eq, sql } from "drizzle-orm";
import { applyTemplateInTransaction } from "./apply-template";
import { TEMPLATES } from "@/lib/templates";
import type { db } from "./index";
import { compCodes, entitlements, workspaces } from "./schema";
import { authorizeStoredProject } from "@/server/actions/project-authz";
import { hasAccountDeletionStartedWith } from "@/server/account-deletion-lifecycle";
import { assertProjectNotDeleting } from "@/server/projects/project-deletion-fence";
import { compRedemptionExpiresAtMs, weddingDateMsForWorkspace } from "./couple-access-term";

type Database = typeof db;
type Failure = { ok: false; reason: "not-found" | "exhausted" | "expired" | "already-redeemed" | "still-provisioning" };
export type CompClaim = Failure | {
  ok: true;
  entitlement: typeof entitlements.$inferSelect;
  codeNotes: string | null;
  sponsorSlug?: string;
  templateRequestId: string;
};

function sponsorSlug(notes: string | null): string | undefined {
  if (!notes) return undefined;
  try {
    const value = JSON.parse(notes) as Record<string, unknown>;
    return value.source_type === "venue_edition" && typeof value.sponsor_slug === "string" && value.sponsor_slug &&
      typeof value.sponsor_name === "string" && value.sponsor_name ? value.sponsor_slug : undefined;
  } catch { return undefined; }
}

/** Claim capacity and the entitlement in one writer transaction. A retry uses
 * the existing grant's stored project, never today's ambient project. */
export async function claimCompEntitlement(database: Database, input: {
  code: string; actorUserId: string; candidateProjectId: string | null; now?: Date;
}): Promise<CompClaim> {
  return withClaimRetry(() => database.transaction(async (tx): Promise<CompClaim> => {
    const now = input.now ?? new Date();
    const [code] = await tx.select().from(compCodes).where(eq(compCodes.code, input.code));
    if (!code) return { ok: false, reason: "not-found" };
    const existing = await tx.select().from(entitlements).where(and(
      eq(entitlements.userId, input.actorUserId), eq(entitlements.source, "comp"),
      eq(entitlements.notes, `comp:${input.code}`),
    ));
    if (existing.length > 1) return { ok: false, reason: "already-redeemed" };
    const prior = existing[0];
    if (prior?.expiresAt && prior.expiresAt.getTime() <= now.getTime()) return { ok: false, reason: "expired" };
    if (!prior && code.expiresAt && code.expiresAt.getTime() <= now.getTime()) return { ok: false, reason: "expired" };
    const projectId = prior ? prior.workspaceId : input.candidateProjectId;
    if (!projectId) return { ok: false, reason: "still-provisioning" };
    const grant = await authorizeStoredProject({
      storedProjectId: projectId, actorUserId: input.actorUserId, capability: "createOrEditTasks",
      archivePolicy: "enforce", executor: tx,
    });
    if (!grant.ok || await hasAccountDeletionStartedWith(tx, input.actorUserId)) return { ok: false, reason: "still-provisioning" };
    await assertProjectNotDeleting(tx, grant.projectId);
    const slug = (prior?.tier ?? code.tier) === "wedding" ? sponsorSlug(code.notes) : undefined;
    const requestId = `comp-template-${createHash("sha256").update(JSON.stringify([input.actorUserId, input.code, grant.projectId])).digest("hex")}`;
    if (prior) return { ok: true, entitlement: prior, codeNotes: code.notes, sponsorSlug: slug, templateRequestId: requestId };
    // Venue fulfilment also writes shared Project setup, beyond task editing.
    if (slug && !grant.capabilities.manageProject) return { ok: false, reason: "still-provisioning" };
    if (code.redeemed >= code.quantity) return { ok: false, reason: "exhausted" };
    const expiresAt = new Date(compRedemptionExpiresAtMs({
      redeemedAtMs: now.getTime(), durationDays: code.durationDays, venueEdition: Boolean(slug),
      weddingDateMs: slug ? await weddingDateMsForWorkspace(tx, grant.projectId) : null,
    }));
    const claimed = await tx.update(compCodes).set({ redeemed: sql`${compCodes.redeemed} + 1` })
      .where(and(eq(compCodes.code, input.code), sql`${compCodes.redeemed} < ${compCodes.quantity}`)).returning({ code: compCodes.code });
    if (claimed.length !== 1) return { ok: false, reason: "exhausted" };
    const [entitlement] = await tx.insert(entitlements).values({
      id: `e-${createHash("sha256").update(JSON.stringify(["comp-claim-v1", input.actorUserId, input.code])).digest("hex").slice(0, 32)}`,
      workspaceId: grant.projectId, userId: input.actorUserId, tier: code.tier, source: "comp",
      startedAt: now, expiresAt, notes: `comp:${input.code}`,
    }).returning();
    if (slug && TEMPLATES.some(template => template.id === "wedding-planning-workspace")) {
      await applyTemplateInTransaction(tx, "wedding-planning-workspace", grant.projectId, input.actorUserId, { requestId });
      await tx.update(workspaces).set({ templateId: "wedding-planning-workspace", activeDomain: "wedding" })
        .where(eq(workspaces.id, grant.projectId));
    }
    return { ok: true, entitlement, codeNotes: code.notes, sponsorSlug: slug, templateRequestId: requestId };
  }, { behavior: "immediate" }));
}

/** Only lock contention is retried automatically, using a fresh transaction.
 * Unknown commit/network outcomes surface; repeating the code reconciles them. */
async function withClaimRetry<T>(work: () => Promise<T>): Promise<T> {
  for (let attempt = 0; ; attempt++) {
    try { return await work(); }
    catch (error) {
      const cause = error as { code?: string; cause?: { code?: string } };
      if (attempt >= 5 || (cause.code !== "SQLITE_BUSY" && cause.cause?.code !== "SQLITE_BUSY")) throw error;
      await new Promise(resolve => setTimeout(resolve, 25 * 2 ** attempt));
    }
  }
}

import "server-only";

import { and, eq, sql } from "drizzle-orm";
import type { CoupleAccessDb } from "./couple-access-term";
import { isVenueEditionCompNotes } from "./couple-access-term";
import { compCodes, entitlements, workspaces } from "./schema";
import { authorizeStoredProject } from "@/server/actions/project-authz";
import { hasAccountDeletionStartedWith } from "@/server/account-deletion-lifecycle";
import { assertProjectNotDeleting } from "@/server/projects/project-deletion-fence";
import { extendedCoupleAccessExpiryMs, normaliseWeddingDateMs } from "@/lib/venue-access-term";
import type { SponsoredWeddingDate, WeddingDateResult, WeddingDateUpdate } from "@/lib/sponsored-wedding-date";

type Reader = Pick<CoupleAccessDb, "select">;

async function sponsoredGrants(database: Reader, projectId: string) {
  const rows = await database.select({
    id: entitlements.id, userId: entitlements.userId,
    startedAt: entitlements.startedAt, expiresAt: entitlements.expiresAt,
    durationDays: compCodes.durationDays, sponsorNotes: compCodes.notes,
  }).from(entitlements).innerJoin(compCodes, eq(entitlements.notes, sql`'comp:' || ${compCodes.code}`))
    .where(and(eq(entitlements.workspaceId, projectId), eq(entitlements.source, "comp"), eq(entitlements.tier, "wedding")));
  return rows.filter(row => isVenueEditionCompNotes(row.sponsorNotes));
}

type Grants = Awaited<ReturnType<typeof sponsoredGrants>>;
function recipientAccess(rows: Grants, actorUserId: string, now: Date): SponsoredWeddingDate["access"] {
  const own = rows.filter(row => row.userId === actorUserId && row.startedAt <= now);
  // Epoch zero is the local revocation sentinel. Elapsed positive terms are
  // distinct: D-022 requires recomputation on a date change, without a cutoff.
  const live = own.filter(row => row.expiresAt === null || row.expiresAt.getTime() > 0);
  if (live.some(row => row.expiresAt === null)) return { status: "active", expiresAt: null };
  const end = Math.max(...live.map(row => row.expiresAt!.getTime()));
  if (Number.isFinite(end)) return { status: end > now.getTime() ? "active" : "expired", expiresAt: new Date(end).toISOString() };
  return { status: own.length ? "revoked" : "none", expiresAt: null };
}

/** Read only the date of the named, freshly authorized sponsored Project. */
export async function readSponsoredWeddingDate(database: Reader, input: { projectId: string; actorUserId: string }, now = new Date()): Promise<SponsoredWeddingDate | null> {
  const [project] = await database.select().from(workspaces).where(eq(workspaces.id, input.projectId)).limit(1);
  if (!project) return null;
  const grant = await authorizeStoredProject({ storedProjectId: project.id, actorUserId: input.actorUserId, capability: "open", archivePolicy: "enforce", executor: database });
  if (!grant.ok || (project.contextType !== "wedding" && project.activeDomain !== "wedding")) return null;
  const rows = await sponsoredGrants(database, project.id);
  if (!rows.length) return null;
  return {
    projectId: project.id, weddingDate: project.primaryDate, revision: project.revision,
    canManage: grant.capabilities.manageProject && !grant.archived,
    access: recipientAccess(rows, input.actorUserId, now),
  };
}

/** Canonical date and project-bound comp terms commit or roll back together. */
export async function updateSponsoredWeddingDate(database: CoupleAccessDb, input: WeddingDateUpdate & { actorUserId: string }, now = new Date()): Promise<WeddingDateResult> {
  if (typeof input.projectId !== "string" || !input.projectId || !Number.isSafeInteger(input.expectedRevision) || input.expectedRevision < 1) return { ok: false, reason: "unavailable" };
  if (input.weddingDate !== null && (typeof input.weddingDate !== "string" || normaliseWeddingDateMs(input.weddingDate) === null)) return { ok: false, reason: "invalid-date" };
  const weddingDate = input.weddingDate?.trim() ?? null;
  return database.transaction(async tx => {
    const [project] = await tx.select().from(workspaces).where(eq(workspaces.id, input.projectId)).limit(1);
    if (!project) return { ok: false, reason: "unavailable" };
    const grant = await authorizeStoredProject({ storedProjectId: project.id, actorUserId: input.actorUserId, capability: "manageProject", archivePolicy: "enforce", executor: tx });
    if (!grant.ok || grant.archived || (project.contextType !== "wedding" && project.activeDomain !== "wedding")) return { ok: false, reason: "unavailable" };
    if (await hasAccountDeletionStartedWith(tx, input.actorUserId) || (project.ownerUserId && await hasAccountDeletionStartedWith(tx, project.ownerUserId))) return { ok: false, reason: "unavailable" };
    await assertProjectNotDeleting(tx, project.id);
    const rows = await sponsoredGrants(tx, project.id);
    if (!rows.length) return { ok: false, reason: "unavailable" };
    if (project.revision !== input.expectedRevision) return { ok: false, reason: "conflict" };

    const changed = project.primaryDate !== weddingDate;
    if (changed) await tx.update(workspaces).set({ primaryDate: weddingDate, primaryDateLabel: "Wedding date", revision: project.revision + 1 }).where(eq(workspaces.id, project.id));
    const weddingDateMs = normaliseWeddingDateMs(weddingDate);
    for (const row of rows) {
      // Never convert revocation, a future grant, or departed/deleting member
      // into new access. Neither account-wide gifts nor purchases enter rows.
      const currentMs = row.expiresAt?.getTime() ?? null;
      if (weddingDateMs === null || currentMs === null || currentMs <= 0 || row.startedAt > now) continue;
      const recipient = await authorizeStoredProject({ storedProjectId: project.id, actorUserId: row.userId, capability: "open", archivePolicy: "enforce", executor: tx });
      if (!recipient.ok || await hasAccountDeletionStartedWith(tx, row.userId)) continue;
      const nextMs = extendedCoupleAccessExpiryMs({ currentExpiresAtMs: currentMs, redeemedAtMs: row.startedAt.getTime(), weddingDateMs, mintedDurationDays: row.durationDays });
      if (nextMs !== null && nextMs > currentMs) {
        await tx.update(entitlements).set({ expiresAt: new Date(nextMs) }).where(eq(entitlements.id, row.id));
        row.expiresAt = new Date(nextMs);
      }
    }
    return { ok: true, data: { projectId: project.id, weddingDate, revision: project.revision + Number(changed), canManage: true, access: recipientAccess(rows, input.actorUserId, now) } };
  }, { behavior: "immediate" });
}

"use server";

import { revalidatePath } from "next/cache";
import { isDemoMode } from "@/lib/access-mode";
import type { WeddingDateResult, WeddingDateUpdate } from "@/lib/sponsored-wedding-date";
import { getCurrentUser } from "@/server/auth";
import { db } from "@/server/db";
import { updateSponsoredWeddingDate } from "@/server/db/sponsored-wedding-date";

export async function saveSponsoredWeddingDate(input: WeddingDateUpdate): Promise<WeddingDateResult> {
  if (isDemoMode()) return { ok: false, reason: "preview" };
  let result: WeddingDateResult;
  try {
    const actorUserId = await getCurrentUser();
    result = await updateSponsoredWeddingDate(db, { ...input, actorUserId });
  } catch {
    return { ok: false, reason: "failed" };
  }
  // A cache failure after commit must not report the durable save as failed.
  if (result.ok) {
    try { revalidatePath("/app", "layout"); } catch { /* next read uses durable state */ }
  }
  return result;
}

/**
 * R-015 · D-022 — the couple access term, in the repository that actually runs
 * the redemption.
 *
 * ── Why this is a port and not a shared module ─────────────────────────────
 * The rule was already implemented, correctly, at
 * `studio/src/lib/venue-edition.ts`. It could not be reached from here.
 * `app` and `studio` are separate git repositories with separate Vercel
 * projects and separate build roots; nothing in a `studio/` path exists on
 * disk when this repository is built. The only sharing mechanism that works
 * across them today is a published npm package (`ds-foundation` is the one
 * precedent), and publishing a package for one arithmetic rule, twenty-nine
 * days before release, buys a release-blocking dependency instead of a fix.
 *
 * So the rule is ported, and the drift that a port invites is answered
 * directly rather than hoped away: `venue-access-term.test.ts` imports the
 * studio module whenever a studio checkout sits beside this one and runs both
 * implementations over the same case matrix, asserting identical answers. It
 * also pins the behaviour with explicit vectors that hold with no studio
 * checkout at all, so CI is not silently weaker than a workstation. If the two
 * rules ever diverge, the test that catches it is in this repository.
 *
 * This mirrors the existing cross-repository lock in
 * `src/server/invitation-code-security.test.ts`, which holds the comp-code
 * alphabet identical to studio's by the same method.
 *
 * ── The rule ───────────────────────────────────────────────────────────────
 * Access ends at `max(redemption + 548 days, wedding date + 90 days)`, and it
 * only ever moves later. Irish venues book twelve to twenty-four months out. A
 * couple who signs in March 2027 for a September 2028 wedding and redeems on
 * the day they sign would, under a flat 548-day term, lose the product before
 * the wedding it was bought for, in public, at the venue that gifted it.
 *
 * Everything here is pure and client-safe. The database callers are
 * `src/server/db/couple-access-term.ts` and, through it,
 * `src/server/actions/comp.ts`.
 */

/** The ratified commercial term. 548 days is the FLOOR, not the answer. */
export const VENUE_EDITION_COUPLE_ACCESS_DAYS = 548;

/** D-010: three months past the wedding date. */
export const VENUE_EDITION_WEDDING_GRACE_DAYS = 90;

const DAY_MS = 24 * 60 * 60 * 1000;

/** A wedding date is a calendar day, so it is carried as UTC midnight. */
const WEDDING_DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Parse a wedding date into the UTC-midnight instant that starts that day.
 * Accepts `YYYY-MM-DD` or an epoch already on a UTC day boundary. Returns null
 * for anything unparseable — a bad date must never silently become "today",
 * because "today" is the one value that shortens access.
 */
export function normaliseWeddingDateMs(
  input: string | number | null | undefined,
): number | null {
  if (input == null) return null;
  if (typeof input === "number") {
    if (!Number.isFinite(input)) return null;
    return Math.floor(input / DAY_MS) * DAY_MS;
  }
  const raw = input.trim();
  if (!WEDDING_DATE_PATTERN.test(raw)) return null;
  const ms = Date.parse(`${raw}T00:00:00.000Z`);
  if (!Number.isFinite(ms)) return null;
  // Date.parse accepts 2026-02-31 and rolls it forward; reject the roll.
  if (new Date(ms).toISOString().slice(0, 10) !== raw) return null;
  return ms;
}

/** The UTC calendar day of an instant, as `YYYY-MM-DD`. */
export function weddingDateLabel(ms: number | null | undefined): string | null {
  if (ms == null || !Number.isFinite(ms)) return null;
  return new Date(ms).toISOString().slice(0, 10);
}

/**
 * D-022 point 2. Access ends at
 *   `max(redemption + 548 days, wedding date + 90 days)`.
 *
 * There is no upper cap: a couple booking three years out gets three years
 * plus the grace period. At roughly EUR 0.10 per live workspace per month the
 * marginal cost is a few euro, against the certainty of the worst failure this
 * product can produce.
 *
 * With no wedding date the floor applies unchanged, which is exactly what
 * shipped before this change — so an unknown date is never worse than the
 * status quo, and can never be shorter than it.
 */
export function coupleAccessExpiryMs(input: {
  redeemedAtMs: number;
  weddingDateMs?: number | null;
  /**
   * The duration the code was minted with, when it is longer than the 548-day
   * floor. A venue that already knew a long-lead wedding date at mint time
   * chose that term deliberately, and a couple who then declines to enter a
   * date must not silently lose it.
   */
  mintedDurationDays?: number | null;
}): number {
  const floorDays = Math.max(
    VENUE_EDITION_COUPLE_ACCESS_DAYS,
    input.mintedDurationDays != null && Number.isFinite(input.mintedDurationDays)
      ? input.mintedDurationDays
      : 0,
  );
  const floor = input.redeemedAtMs + floorDays * DAY_MS;
  const wedding = normaliseWeddingDateMs(input.weddingDateMs ?? null);
  if (wedding == null) return floor;
  return Math.max(floor, wedding + VENUE_EDITION_WEDDING_GRACE_DAYS * DAY_MS);
}

/**
 * The same rule expressed as a mint-time duration, for the case where the
 * wedding date is known before the code is handed over. Always at least the
 * 548-day floor, so a mint can never encode a shorter term than the ratified
 * one.
 */
export function coupleAccessDurationDays(input: {
  issuedAtMs: number;
  weddingDateMs?: number | null;
}): number {
  const expiry = coupleAccessExpiryMs({
    redeemedAtMs: input.issuedAtMs,
    weddingDateMs: input.weddingDateMs,
  });
  return Math.max(
    VENUE_EDITION_COUPLE_ACCESS_DAYS,
    Math.ceil((expiry - input.issuedAtMs) / DAY_MS),
  );
}

/**
 * D-022 point 3. A wedding-date change recomputes expiry, and **access only
 * ever moves later**. A postponement extends it; a correction that would pull
 * it back leaves it where it is.
 *
 * The deliberate consequence: a couple who mistypes 2028 and fixes it to 2027
 * keeps the longer access. Granting a few extra months of a product the venue
 * has already paid for is a far cheaper error than taking access away from
 * someone who has started planning inside it.
 *
 * A null current expiry means the row has no expiry at all. It stays null —
 * this rule extends access, it never introduces an end date that was absent.
 */
export function extendedCoupleAccessExpiryMs(input: {
  currentExpiresAtMs: number | null;
  redeemedAtMs: number;
  weddingDateMs?: number | null;
  mintedDurationDays?: number | null;
}): number | null {
  if (input.currentExpiresAtMs == null) return null;
  const recomputed = coupleAccessExpiryMs({
    redeemedAtMs: input.redeemedAtMs,
    weddingDateMs: input.weddingDateMs,
    mintedDurationDays: input.mintedDurationDays,
  });
  return Math.max(input.currentExpiresAtMs, recomputed);
}

/**
 * The couple-facing sentence for the term, held next to the arithmetic so the
 * two cannot drift. Ratified wording (D-022, brand voice: no em dashes, no
 * exclamation marks, sentence case).
 */
export const COUPLE_ACCESS_TERM_SENTENCE =
  "Eighteen months from the day you redeem, or three months past your wedding, whichever is later.";

"use client";

import { useMemo, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Wordmark } from "@/components/brand/wordmark";
import {
  completeContextualOnboardingAction,
  savePlanningOnboardingDraftAction,
} from "@/server/actions/planning";
import type { PlanningOnboardingState } from "@/server/db/schema";
import {
  CONTEXT_TERMINOLOGY,
  DEFAULT_WORKSPACE_CONTEXT,
  type PlanningPeriodContext,
} from "@/lib/planning/context";
import { normalizeWorkspaceNames } from "@/lib/planning/input";

type Step = PlanningOnboardingState["step"];

type Draft = {
  id: string;
  revision: number;
  contextType: PlanningPeriodContext;
  state: PlanningOnboardingState;
};

const CONTEXT_OPTIONS: ReadonlyArray<{
  id: PlanningPeriodContext;
  eyebrow: string;
  title: string;
  description: string;
}> = [
  {
    id: "school_year",
    eyebrow: "Teacher",
    title: "Classes across a school year",
    description: "Set up each class once. No pupil accounts or pupil data.",
  },
  {
    id: "semester",
    eyebrow: "College student",
    title: "Modules across a semester",
    description: "Each module keeps its own notes, tasks, and plan.",
  },
  {
    id: "wedding_season",
    eyebrow: "Wedding",
    title: "One private wedding workspace",
    description: "Plan towards the wedding date. Sharing stays deliberate.",
  },
  {
    id: "general",
    eyebrow: "General work",
    title: "Projects across active work",
    description: "A finite horizon without changing what your account can do.",
  },
];

export function ContextualOnboarding({
  initialContext,
  initialDraft,
  venueSponsor,
}: {
  initialContext: PlanningPeriodContext | null;
  initialDraft: Draft | null;
  venueSponsor: { id: string; name: string } | null;
}) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [context, setContext] = useState<PlanningPeriodContext | null>(
    initialDraft?.contextType ?? initialContext,
  );
  const [step, setStep] = useState<Step>(
    initialDraft?.state.step ?? (initialContext ? "period" : "context"),
  );
  const [draftRef, setDraftRef] = useState(
    initialDraft ? { id: initialDraft.id, revision: initialDraft.revision } : null,
  );
  const [periodName, setPeriodName] = useState(
    initialDraft?.state.periodName ??
      (initialContext ? CONTEXT_TERMINOLOGY[initialContext].defaultPlanningPeriodName : ""),
  );
  const [startDate, setStartDate] = useState(initialDraft?.state.startDate ?? "");
  const [endDate, setEndDate] = useState(initialDraft?.state.endDate ?? "");
  const [timezone] = useState(initialDraft?.state.timezone ?? "Europe/Dublin");
  const [workspaceText, setWorkspaceText] = useState(
    initialDraft?.state.workspaceNames?.join("\n") ?? "",
  );
  const [primaryDate, setPrimaryDate] = useState(
    initialDraft?.state.primaryDate ?? "",
  );
  const [primaryDateLabel, setPrimaryDateLabel] = useState(
    initialDraft?.state.primaryDateLabel ?? "",
  );
  const [removed, setRemoved] = useState<string[]>([]);
  const [sponsorConsent, setSponsorConsent] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const preview = useMemo(() => {
    try {
      const result = normalizeWorkspaceNames(workspaceText);
      return {
        names: result.names.filter((name) => !removed.includes(name)),
        duplicates: result.duplicates,
      };
    } catch {
      return { names: [] as readonly string[], duplicates: [] as readonly string[] };
    }
  }, [workspaceText, removed]);

  const stateFor = (nextStep: Step): PlanningOnboardingState => ({
    step: nextStep,
    periodName: periodName || undefined,
    startDate: startDate || undefined,
    endDate: endDate || undefined,
    timezone,
    workspaceNames: preview.names,
    primaryDate: primaryDate || undefined,
    primaryDateLabel: primaryDateLabel || undefined,
  });

  const continueTo = (nextStep: Step) => {
    if (!context) return;
    setError(null);
    startTransition(async () => {
      try {
        const saved = await savePlanningOnboardingDraftAction({
          id: draftRef?.id,
          revision: draftRef?.revision,
          contextType: context,
          state: stateFor(nextStep),
        });
        setDraftRef(saved);
        setStep(nextStep);
      } catch (cause) {
        setError(cause instanceof Error ? cause.message : "Your progress did not save.");
      }
    });
  };

  const chooseContext = (next: PlanningPeriodContext) => {
    setContext(next);
    setPeriodName(CONTEXT_TERMINOLOGY[next].defaultPlanningPeriodName);
    setWorkspaceText("");
    setRemoved([]);
    setPrimaryDate("");
    setPrimaryDateLabel(next === "wedding_season" ? "Wedding" : "");
    setStep("period");
  };

  const complete = () => {
    if (!context || preview.names.length === 0) return;
    setError(null);
    startTransition(async () => {
      try {
        await completeContextualOnboardingAction({
          name: periodName,
          contextType: context,
          startDate: startDate || null,
          endDate: endDate || null,
          timezone,
          workspaceNames: [...preview.names],
          workspaceContext: DEFAULT_WORKSPACE_CONTEXT[context],
          primaryDate: primaryDate || null,
          primaryDateLabel: primaryDateLabel || null,
          draftId: draftRef?.id,
          sponsor:
            venueSponsor && sponsorConsent
              ? {
                  id: venueSponsor.id,
                  consentGranted: true,
                  activationLabel: preview.names[0],
                }
              : null,
        });
        router.push("/app/your-work");
        router.refresh();
      } catch (cause) {
        setError(cause instanceof Error ? cause.message : "Your workspaces were not created.");
      }
    });
  };

  const activeIndex = ["context", "period", "workspaces", "review"].indexOf(step);

  return (
    <div className="min-h-screen bg-bg text-ink">
      <header className="flex items-center justify-between px-5 py-5 sm:px-8">
        <Wordmark size="md" />
        <p className="text-[11px] font-medium text-ink-quiet" aria-live="polite">
          Step {activeIndex + 1} of 4
        </p>
      </header>
      <main className="mx-auto flex min-h-[calc(100vh-76px)] w-full max-w-3xl items-center px-5 py-10 sm:px-8">
        <div className="w-full">
          {step === "context" ? (
            <ContextStep onChoose={chooseContext} />
          ) : context ? (
            <>
              <button
                type="button"
                disabled={pending}
                onClick={() =>
                  setStep(step === "review" ? "workspaces" : step === "workspaces" ? "period" : "context")
                }
                className="mb-6 min-h-10 rounded-lg px-2 text-[13px] text-ink-soft outline-none hover:bg-bg-sunken hover:text-ink focus-visible:ring-2 focus-visible:ring-brand/30 disabled:opacity-50"
              >
                ← Back
              </button>
              {step === "period" ? (
                <PeriodStep
                  context={context}
                  periodName={periodName}
                  setPeriodName={setPeriodName}
                  startDate={startDate}
                  setStartDate={setStartDate}
                  endDate={endDate}
                  setEndDate={setEndDate}
                  pending={pending}
                  onContinue={() => continueTo("workspaces")}
                />
              ) : null}
              {step === "workspaces" ? (
                <WorkspaceStep
                  context={context}
                  workspaceText={workspaceText}
                  setWorkspaceText={(value) => {
                    setWorkspaceText(value);
                    setRemoved([]);
                  }}
                  primaryDate={primaryDate}
                  setPrimaryDate={setPrimaryDate}
                  primaryDateLabel={primaryDateLabel}
                  setPrimaryDateLabel={setPrimaryDateLabel}
                  names={preview.names}
                  duplicates={preview.duplicates}
                  onRemove={(name) => setRemoved((value) => [...value, name])}
                  pending={pending}
                  onContinue={() => continueTo("review")}
                />
              ) : null}
              {step === "review" ? (
                <ReviewStep
                  context={context}
                  periodName={periodName}
                  startDate={startDate}
                  endDate={endDate}
                  names={preview.names}
                  primaryDate={primaryDate}
                  venueSponsor={venueSponsor}
                  sponsorConsent={sponsorConsent}
                  setSponsorConsent={setSponsorConsent}
                  pending={pending}
                  onComplete={complete}
                />
              ) : null}
            </>
          ) : null}
          {error ? (
            <p role="alert" className="mt-5 rounded-xl border border-danger/25 bg-danger/5 px-4 py-3 text-[13px] text-danger">
              {error}
            </p>
          ) : null}
        </div>
      </main>
    </div>
  );
}

function ContextStep({ onChoose }: { onChoose: (context: PlanningPeriodContext) => void }) {
  return (
    <section>
      <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-ink-quiet">Shape your work</p>
      <h1 className="mt-3 max-w-[18ch] text-[clamp(2.1rem,7vw,4rem)] font-semibold leading-[0.98] tracking-[-0.05em]">
        What are you planning across?
      </h1>
      <p className="mt-4 max-w-[54ch] text-[15px] leading-6 text-ink-soft">
        This changes the words and starting structure, not what your account can create later.
      </p>
      <div className="mt-8 grid gap-3 sm:grid-cols-2">
        {CONTEXT_OPTIONS.map((option) => (
          <button
            key={option.id}
            type="button"
            onClick={() => onChoose(option.id)}
            className="min-h-32 rounded-2xl border border-line-soft bg-bg-elevated p-5 text-left outline-none transition-colors hover:border-brand/35 focus-visible:border-brand focus-visible:ring-2 focus-visible:ring-brand/25"
          >
            <span className="text-[10px] font-semibold uppercase tracking-[0.14em] text-ink-quiet">{option.eyebrow}</span>
            <span className="mt-2 block text-[16px] font-semibold tracking-[-0.015em] text-ink">{option.title}</span>
            <span className="mt-2 block text-[13px] leading-5 text-ink-soft">{option.description}</span>
          </button>
        ))}
      </div>
    </section>
  );
}

function PeriodStep({
  context,
  periodName,
  setPeriodName,
  startDate,
  setStartDate,
  endDate,
  setEndDate,
  pending,
  onContinue,
}: {
  context: PlanningPeriodContext;
  periodName: string;
  setPeriodName: (value: string) => void;
