}

export async function duplicatePlanningPeriodAction(input: {
  sourcePlanningPeriodId: string;
  newPeriod: PlanningPeriodMutationInput;
  workspaceIds: string[];
  choices: WorkspaceDuplicationChoices;
}): Promise<{ planningPeriodId: string; workspaceIds: string[] }> {
  requirePlanningFeature("planningPeriods");
  requirePlanningFeature("lifecycleDuplication");
  const actorUserId = await getCurrentUser();
  const sourcePeriod = await requirePlanningPeriodOwner(
    actorUserId,
    input.sourcePlanningPeriodId,
  );
  const target = normalizePeriodInput(input.newPeriod, { requireFinite: true });
  if (target.contextType !== sourcePeriod.contextType) {
    throw new Error("A duplicated planning period keeps its context type.");
  }
  const uniqueWorkspaceIds = [...new Set(input.workspaceIds)].slice(0, 50);
  const sources = await Promise.all(
    uniqueWorkspaceIds.map((id) => requireWorkspaceOwner(actorUserId, id)),
  );
  if (
    sources.some(
      (workspace) =>
        workspace.planningPeriodId !== sourcePeriod.id || workspace.archivedAt,
    )
  ) {
    throw new Error("Choose active workspaces from the source planning period.");
  }
  const planningPeriodId = `pp-${randomUUID()}`;
  const copied = await db.transaction(async (tx) => {
    const currentSources = [];
    for (const id of uniqueWorkspaceIds) {
      currentSources.push(
        await requireWorkspaceOwnerInTransaction(tx, actorUserId, id),
      );
    }
    if (
      currentSources.some(
        (workspace) =>
          workspace.planningPeriodId !== sourcePeriod.id || workspace.archivedAt,
      )
    ) {
      throw new Error("Choose active workspaces from the source planning period.");
    }
    await tx.insert(planningPeriods).values({
      id: planningPeriodId,
      ownerUserId: actorUserId,
      ...target,
      position: 1000,
    });
    const result: string[] = [];
    for (const source of currentSources) {
      const workspace = await duplicateProjectIntoPeriodTx(tx, {
        actorUserId,
        source,
        targetPlanningPeriodId: planningPeriodId,
        name: source.name,
        choices: input.choices,
      });
      result.push(workspace.id);
    }
    return result;
  });
  if (copied[0]) await selectWorkspaceCookie(copied[0]);
  revalidatePlanningSurfaces();
  await trackPlanningEvent(actorUserId, "planning_period_created", {
    planning_period_context: target.contextType,
    workspace_count: copied.length,
    source: "lifecycle",
  });
  return { planningPeriodId, workspaceIds: copied };
}

export async function savePlanningOnboardingDraftAction(input: {
  id?: string;
  revision?: number;
  contextType: PlanningPeriodContext;
  state: PlanningOnboardingState;
}): Promise<{ id: string; revision: number }> {
  requirePlanningFeature("contextualOnboarding");
  const actorUserId = await getCurrentUser();
  if (!isPlanningPeriodContext(input.contextType)) {
    throw new Error("Unknown planning period context.");
  }
  const state = normalizeOnboardingState(input.state);
  const now = new Date();
  const expiresAt = new Date(now.getTime() + 30 * 86_400_000);
  if (input.id) {
    const revision = Number.isSafeInteger(input.revision) ? input.revision! : 1;
    const updated = await db
      .update(planningOnboardingSessions)
      .set({
        contextType: input.contextType,
        state,
        revision: revision + 1,
        updatedAt: now,
        expiresAt,
      })
      .where(
        and(
          eq(planningOnboardingSessions.id, input.id),
          eq(planningOnboardingSessions.userId, actorUserId),
          eq(planningOnboardingSessions.status, "in_progress"),
          eq(planningOnboardingSessions.revision, revision),
        ),
      )
      .returning({ id: planningOnboardingSessions.id });
    if (!updated[0]) throw new Error("This onboarding draft changed elsewhere. Reload it.");
    await trackPlanningEvent(actorUserId, "contextual_onboarding_saved", {
      planning_period_context: input.contextType,
      step: state.step,
      source: "onboarding",
      resumed: true,
    });
    return { id: input.id, revision: revision + 1 };
  }
  const id = `onboarding-${randomUUID()}`;
  await db.insert(planningOnboardingSessions).values({
    id,
    userId: actorUserId,
    contextType: input.contextType,
    state,
    expiresAt,
  });
  await trackPlanningEvent(actorUserId, "contextual_onboarding_started", {
    planning_period_context: input.contextType,
    step: state.step,
    source: "onboarding",
  });
  return { id, revision: 1 };
}

export async function getPlanningOnboardingDraftAction(): Promise<{
  id: string;
  revision: number;
  contextType: PlanningPeriodContext;
  state: PlanningOnboardingState;
} | null> {
  requirePlanningFeature("contextualOnboarding");
  const actorUserId = await getCurrentUser();
  const [draft] = await db
    .select({
      id: planningOnboardingSessions.id,
      revision: planningOnboardingSessions.revision,
      contextType: planningOnboardingSessions.contextType,
      state: planningOnboardingSessions.state,
    })
    .from(planningOnboardingSessions)
    .where(
      and(
        eq(planningOnboardingSessions.userId, actorUserId),
        eq(planningOnboardingSessions.status, "in_progress"),
        gt(planningOnboardingSessions.expiresAt, new Date()),
      ),
    )
    .orderBy(desc(planningOnboardingSessions.updatedAt))
    .limit(1);
  return draft ?? null;
}

export type CompleteContextualOnboardingInput = PlanningPeriodMutationInput & {
  workspaceNames: string | string[];
  workspaceContext?: WorkspaceContext;
  primaryDate?: string | null;
  primaryDateLabel?: string | null;
  draftId?: string;
  sponsor?: {
    id: string;
    consentGranted: true;
    activationLabel?: string | null;
  } | null;
};

export async function completeContextualOnboardingAction(
  input: CompleteContextualOnboardingInput,
): Promise<{ planningPeriodId: string; workspaceIds: string[] }> {
  requirePlanningFeature("contextualOnboarding");
  const actorUserId = await getCurrentUser();
  const period = normalizePeriodInput(input, { requireFinite: true });
  const { names } = normalizeWorkspaceNames(input.workspaceNames, { max: 50 });
  const workspaceContext = normalizeWorkspaceContext(
    input.workspaceContext,
    period.contextType,
  );
  if (!isCompatibleWorkspaceContext(period.contextType, workspaceContext)) {
    throw new Error("This workspace type does not match the planning period.");
  }
  if (period.contextType === "wedding_season" && names.length !== 1) {
    throw new Error("A couple starts with one private wedding workspace.");
  }
  const primaryDate = optionalDate(input.primaryDate, "primary date");
  if (period.contextType === "wedding_season" && !primaryDate) {
    throw new Error("Add the wedding date before creating this workspace.");
  }
  const primaryDateLabel =
    input.primaryDateLabel == null || input.primaryDateLabel === ""
      ? null
      : cleanPlainText(input.primaryDateLabel, "Primary date label", 80);
  const planningPeriodId = `pp-${randomUUID()}`;
  const sponsor = await normalizeSponsor(
    input.sponsor,
    period.contextType,
    actorUserId,
  );

  const created = await db.transaction(async (tx) => {
    await tx.insert(planningPeriods).values({
      id: planningPeriodId,
      ownerUserId: actorUserId,
      ...period,
      position: 1000,
    });
    const workspaceRows = await insertWorkspaces(tx, {
      actorUserId,
      planningPeriodId,
      periodContext: period.contextType,
      contextType: workspaceContext,
      names,
      primaryDate,
      primaryDateLabel,
    });
    if (sponsor && workspaceRows[0]) {
      await tx.insert(workspaceSponsorships).values({
        id: `sponsorship-${randomUUID()}`,
        workspaceId: workspaceRows[0].id,
        sponsorId: sponsor.id,
        sponsorRef: sponsor.ref,
        entitlementRef: sponsor.entitlementRef,
        consentReceiptId: sponsor.consentReceiptId,
        consentedMetadata: {
          activationLabel: sponsor.activationLabel ?? undefined,
          primaryDate: primaryDate ?? undefined,
        },
        consentedAt: new Date(),
      });
    }
    if (input.draftId) {
      await tx
        .update(planningOnboardingSessions)
        .set({
          status: "completed",
          completedAt: new Date(),
          updatedAt: new Date(),
          revision: sql`${planningOnboardingSessions.revision} + 1`,
        })
        .where(
          and(
            eq(planningOnboardingSessions.id, input.draftId),
            eq(planningOnboardingSessions.userId, actorUserId),
            eq(planningOnboardingSessions.status, "in_progress"),
          ),
        );
    }
    return workspaceRows;
  });
  if (created[0]) await selectWorkspaceCookie(created[0].id);
  if (period.contextType === "wedding_season") {
    await applyWeddingDateToCoupleAccess(actorUserId, primaryDate);
  }
  revalidatePlanningSurfaces();
  await trackPlanningEvent(actorUserId, "contextual_onboarding_completed", {
    planning_period_context: period.contextType,
    workspace_context: workspaceContext,
    workspace_count: created.length,
    source: "onboarding",
  });
  return {
    planningPeriodId,
    workspaceIds: created.map((workspace) => workspace.id),
  };
}

async function insertWorkspaces(
  tx: DatabaseTransaction,
  input: {
    actorUserId: string;
    planningPeriodId: string;
    periodContext: PlanningPeriodContext;
    contextType: WorkspaceContext;
    names: readonly string[];
    primaryDate: string | null;
    primaryDateLabel: string | null;
  },
): Promise<Array<{ id: string; name: string; slug: string }>> {
  if (input.names.length === 0) return [];
  const [last] = await tx
    .select({ position: workspaces.position })
    .from(workspaceMembers)
    .innerJoin(workspaces, eq(workspaces.id, workspaceMembers.workspaceId))
    .where(
      and(
        eq(workspaceMembers.userId, input.actorUserId),
        eq(workspaces.planningPeriodId, input.planningPeriodId),
      ),
    )
    .orderBy(desc(workspaces.position))
    .limit(1);
  const created: Array<{ id: string; name: string; slug: string }> = [];
  let position = (last?.position ?? 0) + 1000;
  const now = new Date();
  for (const name of input.names) {
    const id = `ws-${randomUUID()}`;
    const slug = `${slugifyProjectName(name)}-${randomUUID().slice(0, 8)}`;
    await tx.insert(workspaces).values({
      id,
      slug,
      name,
      ownerUserId: input.actorUserId,
      planningPeriodId: input.planningPeriodId,
      contextType: input.contextType,
      primaryDate: input.primaryDate,
      primaryDateLabel: input.primaryDateLabel,
      position,
      activeDomain: PROJECT_ACTIVE_DOMAIN[input.periodContext],
      primaryUseCase: PROJECT_PRIMARY_USE_CASE[input.periodContext],
      onboardingCompletedAt: now,
      updatedAt: now,
    });
    await tx.insert(workspaceMembers).values({
      workspaceId: id,
      userId: input.actorUserId,
      role: "owner",
    });
    created.push({ id, name, slug });
    position += 1000;
  }
  return created;
}

function normalizeOnboardingState(
  input: PlanningOnboardingState,
): PlanningOnboardingState {
  if (!input || !["context", "period", "workspaces", "review"].includes(input.step)) {
    throw new Error("Unknown onboarding step.");
  }
  const timezone = input.timezone ?? "UTC";
  assertIanaTimeZone(timezone);
  return {
    step: input.step,
    periodName: input.periodName
      ? cleanPlainText(input.periodName, "Name", 100)
      : undefined,
    startDate: optionalDate(input.startDate, "start date") ?? undefined,
    endDate: optionalDate(input.endDate, "end date") ?? undefined,
    timezone,
    workspaceNames: input.workspaceNames
      ?.filter((value): value is string => typeof value === "string")
      .slice(0, 50)
      .map((value) => cleanPlainText(value, "Workspace name", 100)),
    primaryDate: optionalDate(input.primaryDate, "primary date") ?? undefined,
    primaryDateLabel: input.primaryDateLabel
      ? cleanPlainText(input.primaryDateLabel, "Primary date label", 80)
      : undefined,
  };
}

async function normalizeSponsor(
  sponsor: CompleteContextualOnboardingInput["sponsor"],
  context: PlanningPeriodContext,
  actorUserId: string,
) {
  if (!sponsor) return null;
  if (context !== "wedding_season") {
    throw new Error("Sponsorship is only accepted in the wedding activation flow.");
  }
  if (sponsor.consentGranted !== true) {
    throw new Error("Consent is required before sharing activation metadata.");
  }
  const verified = await detectVenueWelcomeForLegacyPlanning(actorUserId);
  if (!verified || verified.sponsorSlug !== sponsor.id) {
    throw new Error("The venue activation could not be verified.");
  }
  return {
    id: verified.sponsorSlug,
    ref: null,
    entitlementRef: `sha256:${createHash("sha256").update(verified.code).digest("hex")}`,
    consentReceiptId: `consent-${randomUUID()}`,
    activationLabel: sponsor.activationLabel
      ? cleanPlainText(sponsor.activationLabel, "Activation label", 100)
      : null,
  };
}

async function selectWorkspaceCookie(workspaceId: string): Promise<void> {
  const store = await cookies();
  store.set(ACTIVE_WORKSPACE_COOKIE_NAME, workspaceId, {
    path: "/",
    sameSite: "lax",
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    maxAge: 60 * 60 * 24 * 30,
  });
}

function revalidatePlanningSurfaces(): void {
  revalidatePath("/app", "layout");
  revalidatePath("/app/your-work");
  revalidatePath("/welcome/plan");
}

import { and, eq, isNotNull, like } from "drizzle-orm";
import type { LibSQLDatabase } from "drizzle-orm/libsql";
import * as schema from "./schema";
import { compCodes, entitlements, workspaces } from "./schema";
import {
  coupleAccessExpiryMs,
  extendedCoupleAccessExpiryMs,
  normaliseWeddingDateMs,
} from "@/lib/venue-access-term";

/**
 * R-015 · D-022 — the database seam for the couple access term.
 *
 * The arithmetic lives in `@/lib/venue-access-term` (pure, ported from
 * `studio/src/lib/venue-edition.ts`, held identical by a differential test).
 * This file is the thin layer that decides which rows the rule applies to and
 * writes the result. It deliberately does NOT import `server-only`, for the
 * same reason `account-erasure.ts` does not: the database handle is a
 * parameter, so the whole thing can be exercised against an in-memory libSQL
 * instance rather than only in production.
 *
 * ── What the app knows about a wedding date, stated plainly ────────────────
 * The app has no `wedding_date` column on `entitlements`, and this change does
 * not add one. The couple's date already has a home: `workspaces.primary_date`
 * (`schema.ts`), captured by the wedding branch of contextual onboarding. The
 * term is therefore computed from whatever date is on the couple's workspace
 * at the moment it is asked for, and recomputed when that date is written.
 *
 * Existing sponsored Projects now capture and update that canonical date via
 * `server/actions/sponsored-wedding-date.ts` and its transactional DB helper.
 * That path is Project-scoped and preserves revoked grants. The user-wide
 * helper below remains the legacy experimental onboarding entry point; it is
 * not used for updates to an existing sponsored Project. Neither path retimes
 * existing tasks merely because the wedding date changed.
 */

export type CoupleAccessDb = LibSQLDatabase<typeof schema>;

const DAY_MS = 24 * 60 * 60 * 1000;

type CompNotes = {
  sponsor_slug?: string;
  sponsor_name?: string;
  source_type?: string;
};

/**
 * A comp code is a Venue Edition couple licence when its notes carry the
 * sponsor JSON that `studio/scripts/issue-codes.ts` writes. Same predicate
 * `venue-welcome.ts` uses to resolve the sponsor, restated here as a pure
 * function so the term decision does not need a database round trip or a
 * `server-only` import.
 */
export function isVenueEditionCompNotes(notes: string | null): boolean {
  if (!notes) return false;
  let parsed: CompNotes;
  try {
    parsed = JSON.parse(notes) as CompNotes;
  } catch {
    return false;
  }
  return (
    typeof parsed.sponsor_slug === "string" &&
    parsed.sponsor_slug.length > 0 &&
    typeof parsed.sponsor_name === "string" &&
    parsed.sponsor_name.length > 0 &&
    parsed.source_type === "venue_edition"
  );
}

/**
 * The one place a comp redemption's expiry is decided.
 *
 * What this replaces, and why it was the most serious open defect in the
 * programme: `redeemCompCodeImpl` computed
 * `new Date(Date.now() + row.durationDays * 24 * 60 * 60 * 1000)` for every
 * code, Venue Edition included. That is a flat term. D-022 ratified
 * `max(redemption + 548 days, wedding date + 90 days)` and it was implemented
 * only in the repository that does not run the redemption.
 *
 * Non-Venue-Edition codes (the student code, ordinary gifts) keep the flat
 * duration they have always had. Nothing about them changes.
 */
export function compRedemptionExpiresAtMs(input: {
  venueEdition: boolean;
  durationDays: number;
  redeemedAtMs: number;
  weddingDateMs: number | null;
}): number {
  if (input.venueEdition) {
    return coupleAccessExpiryMs({
      redeemedAtMs: input.redeemedAtMs,
      weddingDateMs: input.weddingDateMs,
      mintedDurationDays: input.durationDays,
    });
  }
  return input.redeemedAtMs + input.durationDays * DAY_MS;
}

/**
 * The wedding date recorded on a workspace, or null.
 *
 * `primary_date` is a general-purpose field: on a student workspace it is an
 * exam, on a project it is a launch. It is read as a wedding date ONLY on a
 * wedding workspace, so an unrelated date can never reach the term
 * calculation. Returning null is always safe: the term falls back to the
 * 548-day floor.
 */
export async function weddingDateMsForWorkspace(
  database: Pick<CoupleAccessDb, "select">,
  workspaceId: string,
): Promise<number | null> {
  if (!workspaceId) return null;
  const [row] = await database
    .select({
      primaryDate: workspaces.primaryDate,
      contextType: workspaces.contextType,
      activeDomain: workspaces.activeDomain,
    })
    .from(workspaces)
    .where(eq(workspaces.id, workspaceId))
    .limit(1);
  if (!row?.primaryDate) return null;
  const isWedding =
    row.contextType === "wedding" || row.activeDomain === "wedding";
  if (!isWedding) return null;
  return normaliseWeddingDateMs(row.primaryDate);
}

export type WeddingDateExtension = {
  /** Entitlement rows whose expiry moved later. */
  extended: number;
  /** Rows inspected and left exactly as they were. */
  unchanged: number;
};

/**
 * D-022 point 3 — a wedding date arriving after redemption recomputes the
 * term, and **the term only ever moves later**.
 *
 * Matched on the user rather than the workspace on purpose. The entitlement is
 * bound to whichever workspace was active at redemption, and a couple who then
 * runs wedding onboarding creates a *different* workspace to hold the date. The
 * term belongs to the couple, not to a row in `workspaces`.
 *
 * Every write is `Math.max(current, recomputed)` via
 * `extendedCoupleAccessExpiryMs`, so:
 *   - a postponement extends access,
 *   - a correction that would pull the date earlier changes nothing,
 *   - an unparseable or absent date changes nothing,
 *   - an entitlement with no expiry at all keeps having none.
 * There is no branch in this function that can shorten a term.
 */
export async function extendCoupleAccessForWeddingDate(
  database: CoupleAccessDb,
  input: { userId: string; weddingDate: string | number | null | undefined },
): Promise<WeddingDateExtension> {
  const result: WeddingDateExtension = { extended: 0, unchanged: 0 };
  if (!input.userId) return result;
  const weddingDateMs = normaliseWeddingDateMs(input.weddingDate ?? null);
  if (weddingDateMs == null) return result;

  const rows = await database
    .select({
      id: entitlements.id,
      startedAt: entitlements.startedAt,
      expiresAt: entitlements.expiresAt,
      notes: entitlements.notes,
    })
    .from(entitlements)
    .where(
      and(
        eq(entitlements.userId, input.userId),
        eq(entitlements.tier, "wedding"),
        eq(entitlements.source, "comp"),
        isNotNull(entitlements.notes),
        like(entitlements.notes, "comp:%"),
      ),
    );

  for (const row of rows) {
    const code = (row.notes ?? "").replace(/^comp:/, "");
    if (!code) continue;
    const [comp] = await database
      .select({
        notes: compCodes.notes,
        durationDays: compCodes.durationDays,
      })
      .from(compCodes)
      .where(eq(compCodes.code, code))
      .limit(1);
    if (!comp || !isVenueEditionCompNotes(comp.notes)) continue;

    const currentMs = row.expiresAt ? row.expiresAt.getTime() : null;
    const nextMs = extendedCoupleAccessExpiryMs({
      currentExpiresAtMs: currentMs,
      redeemedAtMs: row.startedAt.getTime(),
      weddingDateMs,
      mintedDurationDays: comp.durationDays,
    });
    if (nextMs == null || currentMs == null || nextMs <= currentMs) {
      result.unchanged += 1;
      continue;
    }
    // Guarded on the expiry this decision was made against, so a concurrent
    // writer that already moved the row later cannot be overwritten with an
    // earlier value. Losing this race is a no-op, never a shortening.
    const moved = await database
      .update(entitlements)
      .set({ expiresAt: new Date(nextMs) })
      .where(
        and(
          eq(entitlements.id, row.id),
          eq(entitlements.expiresAt, row.expiresAt as Date),
        ),
      )
      .returning({ id: entitlements.id });
    if (moved.length > 0) result.extended += 1;
    else result.unchanged += 1;
  }
  return result;
}

